extern printf(fmt: string, ...);

frame main() ret int {
    local age: int = 18;

    # Simple if - only runs if condition is true
    if (age >= 18) {
        printf("You are an adult!\n");
    }

    local temperature: int = 35;

    if (temperature > 30) {
        printf("It's hot outside!\n");
    }

    # The condition must be in parentheses
    local score: int = 85;

    if (score >= 60) {
        printf("You passed!\n");
    }

    return 0;
}

extern printf(fmt: string, ...);

frame main() ret int {
    local number: int = 7;

    # Check if even or odd
    if (number % 2 == 0) {
        printf("%d is even\n", number);
    } else {
        printf("%d is odd\n", number);
    }

    local balance: float = 150.50;

    # Check account status
    if (balance >= 0.0) {
        printf("Balance: $%.2f (OK)\n", balance);
    } else {
        printf("Balance: $%.2f (OVERDRAWN!)\n", balance);
    }

    return 0;
}

extern printf(fmt: string, ...);

frame main() ret int {
    local score: int = 85;

    # Grade calculation
    if (score >= 90) {
        printf("Grade: A\n");
    } else if (score >= 80) {
        printf("Grade: B\n");
    } else if (score >= 70) {
        printf("Grade: C\n");
    } else if (score >= 60) {
        printf("Grade: D\n");
    } else {
        printf("Grade: F\n");
    }

    # Another example: day of week
    local day: int = 3;  # 1=Mon, 2=Tue, etc.

    if (day == 1) {
        printf("Monday\n");
    } else if (day == 2) {
        printf("Tuesday\n");
    } else if (day == 3) {
        printf("Wednesday\n");
    } else if (day == 4) {
        printf("Thursday\n");
    } else if (day == 5) {
        printf("Friday\n");
    } else {
        printf("Weekend!\n");
    }

    return 0;
}

extern printf(fmt: string, ...);

frame main() ret int {
    local age: int = 25;
    local hasLicense: bool = true;
    local hasInsurance: bool = true;

    # Nested conditions for driving eligibility
    if (age >= 16) {
        printf("Old enough to drive\n");

        if (hasLicense) {
            printf("Has a license\n");

            if (hasInsurance) {
                printf("Fully legal to drive!\n");
            } else {
                printf("Need insurance first!\n");
            }
        } else {
            printf("Need to get a license first!\n");
        }
    } else {
        printf("Too young to drive\n");
    }

    return 0;
}

extern printf(fmt: string, ...);

frame main() ret int {
    local age: int = 25;
    local hasID: bool = true;
    local isMember: bool = false;

    # Using && (AND) - ALL conditions must be true
    if (age >= 21 && hasID) {
        printf("Entry allowed (age and ID check passed)\n");
    }

    # Using || (OR) - ANY condition can be true
    if (isMember || age >= 65) {
        printf("Discount applies!\n");
    } else {
        printf("Regular price\n");
    }

    # Complex combinations
    local isStudent: bool = true;
    local income: int = 15000;

    if ((isStudent && income < 20000) || age < 18) {
        printf("Qualifies for assistance program\n");
    }

    return 0;
}

extern printf(fmt: string, ...);

frame main() ret int {
    local score: int = 75;

    # Ternary operator: condition ? value_if_true : value_if_false
    local status: string = score >= 60 ? "Pass" : "Fail";
    printf("Status: %s\n", status);

    # Useful for inline decisions
    local age: int = 15;
    local category: string = age >= 18 ? "Adult" : "Minor";
    printf("Category: %s\n", category);

    # Can be used directly in expressions
    local a: int = 10;
    local b: int = 20;
    local max: int = a > b ? a : b;
    printf("Max of %d and %d is %d\n", a, b, max);

    return 0;
}

