extern printf(fmt: string, ...);

frame main() ret int {
    local num: int = -7;

    if (num > 0) {
        printf("%d is positive\n", num);
        if (num % 2 == 0) {
            printf("And it's even\n");
        } else {
            printf("And it's odd\n");
        }
    } else if (num < 0) {
        printf("%d is negative\n", num);
    } else {
        printf("%d is zero\n", num);
    }

    return 0;
}
